import cv2
import os
import numpy as np


def verify_normalized_bboxes(img_path, bboxes, save_path=None, format='yolo'):
    """
    验证并绘制归一化标签到图像上。

    Args:
        img_path (str): 图像文件的绝对路径。
        bboxes (list): 归一化标签列表。
                       如果是 YOLO 格式，期望为 [[x_center, y_center, width, height], ...]
                       数值范围应在 0.0 到 1.0 之间。
        save_path (str): 结果保存路径。
        format (str): 'yolo' 代表 [xc, yc, w, h], 'voc' 代表 [xmin, ymin, xmax, ymax]
    """
    # 1. 路径与读取检查
    if not os.path.exists(img_path):
        print(f"[Error] 图像不存在: {img_path}")
        return

    img = cv2.imread(img_path)
    if img is None:
        print(f"[Error] 无法读取图像: {img_path}")
        return

    # 获取图像尺寸 (高度, 宽度)
    h_img, w_img = img.shape[:2]
    print(f"[Info] 图像尺寸: W={w_img}, H={h_img}")

    # 2. 绘图配置
    color = (0, 0, 255)  # 红色 (B, G, R)
    thickness = 2

    print(f"[Info] 处理 {len(bboxes)} 个目标...")

    for i, box in enumerate(bboxes):
        # 确保数据是浮点型
        box = list(map(float, box))

        # 提取坐标 (假设输入只有4个坐标值，如果有class_id需要切片，如 box[1:])
        # 这里假设输入纯坐标列表: [v1, v2, v3, v4]
        v1, v2, v3, v4 = box[0], box[1], box[2], box[3]

        if format == 'yolo':
            # YOLO 格式: x_center, y_center, width, height (全部归一化)
            # 1. 反归一化
            xc = v1 * w_img
            yc = v2 * h_img
            w = v3 * w_img
            h = v4 * h_img

            # 2. 转换为左上角和右下角 (xyxy)
            x1 = int(xc - w / 2)
            y1 = int(yc - h / 2)
            x2 = int(xc + w / 2)
            y2 = int(yc + h / 2)

        elif format == 'voc':
            # VOC 归一化格式: xmin, ymin, xmax, ymax (全部归一化)
            x1 = int(v1 * w_img)
            y1 = int(v2 * h_img)
            x2 = int(v3 * w_img)
            y2 = int(v4 * h_img)

        # 边界截断，防止画出图外
        x1, y1 = max(0, x1), max(0, y1)
        x2, y2 = min(w_img, x2), min(h_img, y2)

        # 3. 绘制
        cv2.rectangle(img, (x1, y1), (x2, y2), color, thickness)

        # 标注坐标信息用于调试
        label = f"ID:{i} yolo"
        cv2.putText(img, label, (x1, y1 - 5), cv2.FONT_HERSHEY_SIMPLEX, 0.5, color, 1)

    # 3. 保存结果
    if save_path is None:
        name, ext = os.path.splitext(img_path)
        save_path = f"{name}_norm_verified{ext}"

    os.makedirs(os.path.dirname(save_path), exist_ok=True)
    cv2.imwrite(save_path, img)
    print(f"[Success] 结果已保存至: {save_path}")


